def col(key, num, line, hook, subhook, tt, igq, yt, ytd, pt, pd, pin_title, hook_type="surprise"):
    return dict(C, key=key, num=num, hook_type=hook_type, tag="WATCH IT FILL IN", hook=hook, subhook=subhook,
                pin_title=pin_title, pin_sub="See it colored in · ages 3–8", tt=tt,
                ig=f"{igq}\n\n“{line}” Page {num} of 50 in our Cozy Christmas coloring story. Swipe to watch it fill in." + COL_IG,
                tags=CTAGS, yt=yt, ytd=ytd, pt=pt, pd=pd)


